    return this.http.post<ManufacturerDto>(`${ROOT}/manufacturers`, m);
  }
  deleteManufacturer(id: number): Observable<void> {
    return this.http.delete<void>(`${ROOT}/manufacturers/${id}`);
  }
  getAverageRatings(): Observable<ManufacturerRatingDto[]> {
    return this.http.get<ManufacturerRatingDto[]>(`${ROOT}/manufacturers/ratings`);
  }

  getRatings(): Observable<RatingDto[]> {
    return this.http.get<RatingDto[]>(`${ROOT}/ratings`);
  }
  saveRating(r: RatingDto): Observable<RatingDto> {
    return this.http.post<RatingDto>(`${ROOT}/ratings`, r);
  }
  deleteRating(id: number): Observable<void> {
    return this.http.delete<void>(`${ROOT}/ratings/${id}`);
