input.command:
for p in $(pgrep -f "[D]evAppServerMain"); do kill $p; done; sleep 4; (setsid sh /work/backend/run.sh > /tmp/server.log 2>&1 &); for i in $(seq 1 60); do curl -s -o /dev/null http://localhost:8888/api/manufacturers && break; sleep 2; done
cat > /tmp/t/report.js <<'EOF'
const WebSocket = require('/work/node_modules/ws');
(async () => {
  const tgt = await (await fetch('http://localhost:9222/json/new?about:blank', {method:'PUT'})).json();
  const ws = new WebSocket(tgt.webSocketDebuggerUrl); await new Promise(r => ws.on('open', r));
  let id = 0; const pending = {};
  ws.on('message', m => { const d = JSON.parse(m); if (d.id && pending[d.id]) pending[d.id](d); });
  const send = (method, params={}) => new Promise(r => { const i = ++id; pending[i] = r; ws.send(JSON.stringify({id:i, method, params})); });
  const ev = async (e) => (await send('Runtime.evaluate', {expression:e, awaitPromise:true, returnByValue:true})).result.result.value;
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  await send('Network.enable'); await send('Network.setCacheDisabled',{cacheDisabled:true});
  await send('Page.navigate', {url:'http://localhost:8888/ng/#rating'}); await sleep(2000);
  // as the step defs: read Car and Rating columns by header index from the ratings table
  const ratings = await ev(`(()=>{const t=document.getElementById('gwt-debug-ratings');const h=[...t.querySelectorAll('thead th')].map(x=>x.innerText);const ci=h.indexOf('Car'),ri=h.indexOf('Rating');return [...t.querySelectorAll('tbody')[0].querySelectorAll('tr')].map(r=>[r.children[ci].innerText,r.children[ri].innerText]);})()`);
  const avg = {}; for (const [car, rating] of ratings) { const m = car.substring(0, car.indexOf('/')); (avg[m] ||= []).push(Number(rating)); }
  await ev(`document.querySelector('#gwt-debug-menubar a[href*=report]').click()`); await sleep(1500);
  const rep = await ev(`(()=>{const t=document.getElementById('gwt-debug-reports');const h=[...t.querySelectorAll('thead th')].map(x=>x.innerText);const mi=h.indexOf('Manufacturer'),ri=h.indexOf('Rating');return [h,[...t.querySelectorAll('tbody')[0].querySelectorAll('tr')].map(r=>[r.children[mi].innerText,r.children[ri].innerText])];})()`);
  console.log('ratings', JSON.stringify(ratings)); console.log('report', JSON.stringify(rep));
  let match = rep[1].length > 0;
  for (const [m, a] of rep[1]) { const xs = avg[m]; const ref = xs.reduce((s,x)=>s+x,0)/xs.length; if (!(Math.abs(Number(a)-ref) < 0.001)) match = false; }
  console.log('MATCH', match); process.exit(0);
})();
EOF
node /tmp/t/report.js

